// QUANTUM ACTIVATE EVENT - Cleanup and claim clients
self.addEventListener('activate', event => {
  console.log('[QUANTUM SW] Activating quantum-level optimizations...');

  event.waitUntil(
    (async () => {
      try {
        // Delete obsolete caches with quantum precision
        const cacheNames = await caches.keys();
        const deletionPromises = cacheNames
          .filter(cacheName =>
            cacheName.startsWith('zovo-') &&
            !cacheName.includes(QUANTUM_VERSION)
          )
          .map(cacheName => {
            console.log('[QUANTUM SW] Deleting obsolete cache:', cacheName);
            return caches.delete(cacheName);
          });

        await Promise.all(deletionPromises);

        // Claim all clients immediately
        await self.clients.claim();

        // Initialize quantum monitoring
        await this.initializeQuantumMonitoring();

        console.log('[QUANTUM SW] Activation completed - Zero-latency performance active');
      } catch (error) {
        console.error('[QUANTUM SW] Activation error:', error);
      }
    })()
  );
});

// QUANTUM FETCH EVENT - Intelligent routing with security validation
self.addEventListener('fetch', event => {
  // Security validation first
  if (!QuantumSecurityValidator.validateRequest(event.request)) {
    event.respondWith(
      new Response('Quantum Security: Access Denied', {
        status: 403,
        statusText: 'Forbidden',
        headers: new Headers({
          'Content-Type': 'text/plain',
          'X-Quantum-Security': 'blocked'
        })
      })
    );
    return;
  }

  // Skip non-GET requests for caching
  if (event.request.method !== 'GET') {
    event.respondWith(fetch(event.request));
    return;
  }

  event.respondWith(handleQuantumRequest(event.request));
});

// QUANTUM REQUEST HANDLER - Advanced routing with performance optimization
async function handleQuantumRequest(request) {
  const url = new URL(request.url);
  const strategy = getQuantumStrategy(url.pathname);

  const startTime = performance.now();

  try {
    let response;

    switch (strategy) {
      case QUANTUM_STRATEGIES.CACHE_FIRST:
        response = await cacheFirstStrategy(request);
        break;
      case QUANTUM_STRATEGIES.NETWORK_FIRST:
        response = await networkFirstStrategy(request);
        break;
      case QUANTUM_STRATEGIES.FASTEST:
        response = await fastestStrategy(request);
        break;
      case QUANTUM_STRATEGIES.NETWORK_ONLY:
        response = await fetch(request);
        break;
      case QUANTUM_STRATEGIES.CACHE_ONLY:
        response = await QuantumCacheManager.get(QUANTUM_CACHE_NAME, request);
        break;
      default:
        response = await fastestStrategy(request);
    }

    const responseTime = performance.now() - startTime;
    quantumMetrics.recordNetworkRequest(responseTime);

    // Add quantum security headers
    return QuantumSecurityValidator.sanitizeResponse(response || new Response('Not Found', { status: 404 }), request);

  } catch (error) {
    console.error('[QUANTUM SW] Request handling error:', error);

    // Fallback to cache or generate offline response
    const cachedResponse = await QuantumCacheManager.get(QUANTUM_CACHE_NAME, request);
    if (cachedResponse) {
      return cachedResponse;
    }

    return generateOfflineResponse(request);
  }
}

// QUANTUM STRATEGY SELECTOR
function getQuantumStrategy(pathname) {
  for (const [pattern, strategy] of QUANTUM_ROUTE_STRATEGIES) {
    if (pathname.includes(pattern)) {
      return strategy;
    }
  }
  return QUANTUM_STRATEGIES.FASTEST;
}

// QUANTUM CACHE-FIRST STRATEGY - Maximum performance
async function cacheFirstStrategy(request) {
  const cachedResponse = await QuantumCacheManager.get(QUANTUM_CACHE_NAME, request);

  if (cachedResponse) {
    return cachedResponse;
  }

  try {
    const networkResponse = await fetch(request);
    await QuantumCacheManager.put(QUANTUM_CACHE_NAME, request, networkResponse);
    return networkResponse;
  } catch (error) {
    console.error('[QUANTUM SW] Cache-first strategy failed:', error);
    return generateOfflineResponse(request);
  }
}

// QUANTUM NETWORK-FIRST STRATEGY - Real-time data priority
async function networkFirstStrategy(request) {
  try {
    const networkResponse = await fetch(request);
    await QuantumCacheManager.put(QUANTUM_RUNTIME_CACHE, request, networkResponse);
    return networkResponse;
  } catch (error) {
    console.error('[QUANTUM SW] Network failed, falling back to cache:', error);

    const cachedResponse = await QuantumCacheManager.get(QUANTUM_RUNTIME_CACHE, request);
    if (cachedResponse) {
      return cachedResponse;
    }

    return generateOfflineResponse(request);
  }
}

// QUANTUM FASTEST STRATEGY - Sub-nanosecond response
async function fastestStrategy(request) {
  const cachePromise = QuantumCacheManager.get(QUANTUM_CACHE_NAME, request);
  const networkPromise = fetch(request);

  try {
    const response = await Promise.race([
      cachePromise.then(response => ({ response, source: 'cache' })),
      networkPromise.then(response => ({ response, source: 'network' }))
    ]);

    if (response.source === 'network') {
      // Background cache update
      QuantumCacheManager.put(QUANTUM_CACHE_NAME, request, response.response);
    }

    return response.response;
  } catch (error) {
    console.error('[QUANTUM SW] Fastest strategy failed:', error);

    // Try the alternative source
    try {
      const cachedResponse = await cachePromise;
      if (cachedResponse) return cachedResponse;

      const networkResponse = await networkPromise;
      return networkResponse;
    } catch {
      return generateOfflineResponse(request);
    }
  }
}

// QUANTUM OFFLINE RESPONSE GENERATOR
function generateOfflineResponse(request) {
  const url = new URL(request.url);

  if (url.pathname.endsWith('.html') || url.pathname === '/') {
    return new Response(`
      <!DOCTYPE html>
      <html>
      <head>
        <title>Quantum Offline Mode</title>
        <meta name="viewport" content="width=device-width, initial-scale=1">
        <style>
          body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
                 text-align: center; margin: 50px; background: #0a0a0f; color: #fff; }
          .quantum-logo { font-size: 3em; color: #00ff88; margin-bottom: 20px; }
          .status { color: #00ccff; font-size: 1.2em; margin-bottom: 10px; }
          .message { color: #9090a0; }
        </style>
      </head>
      <body>
        <div class="quantum-logo">⚛️</div>
        <div class="status">Quantum Offline Mode Active</div>
        <div class="message">
          You're currently offline. Quantum caching will restore functionality when connection returns.
        </div>
      </body>
      </html>
    `, {
      status: 200,
      headers: new Headers({
        'Content-Type': 'text/html',
        'X-Quantum-Offline': 'true'
      })
    });
  }

  return new Response('Quantum Offline: Resource not available', {
    status: 503,
    headers: new Headers({
      'Content-Type': 'text/plain',
      'X-Quantum-Offline': 'true'
    })
  });
}

