// QUANTUM ANALYTICS SYNC
async function syncQuantumAnalytics() {
  try {
    const analyticsData = await getStoredAnalytics();

    if (analyticsData.length > 0) {
      const metrics = quantumMetrics.getReport();

      for (const data of analyticsData) {
        await fetch('/api/quantum-analytics', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'X-Quantum-Analytics': 'true'
          },
          body: JSON.stringify({
            ...data,
            quantumMetrics: metrics,
            timestamp: Date.now()
          })
        });
      }

      await clearAnalyticsQueue();
      console.log('[QUANTUM SW] Analytics sync completed');
    }
  } catch (error) {
    console.error('[QUANTUM SW] Analytics sync failed:', error);
  }
}

