// QUANTUM UTILITY FUNCTIONS
async function getStoredAnalytics() {
  try {
    const db = await openQuantumDB();
    const transaction = db.transaction(['analytics'], 'readonly');
    const store = transaction.objectStore('analytics');
    const request = store.getAll();

    return new Promise((resolve, reject) => {
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  } catch {
    return [];
  }
}

async function clearAnalyticsQueue() {
  try {
    const db = await openQuantumDB();
    const transaction = db.transaction(['analytics'], 'readwrite');
    const store = transaction.objectStore('analytics');
    await store.clear();
  } catch (error) {
    console.error('[QUANTUM SW] Analytics queue clear failed:', error);
  }
}

async function openQuantumDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open('QuantumAnalytics', 1);

    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve(request.result);

    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains('analytics')) {
        db.createObjectStore('analytics', { keyPath: 'id', autoIncrement: true });
      }
    };
  });
}

